// entity 6
// Runtime spawner: the plate fires spawnFromSpawner, materializing count
// fresh reference_enemy AI enemies at this origin. count enemies fan out
// along the spawner local +X axis, spaced by the AI capsule diameter; keep
// the origin clear of the nook walls in that direction. archetype must name
// a registered AI-enemy canonical name; reference_enemy is globally
// registered by start-script.js.
{
"classname" "entity_spawner"
"origin" "224 -16 16"
"angles" "0 180 0"
"archetype" "reference_enemy"
"count" "3"
"_tags" "closet_spawner"
}
